import{_ as s}from"./chunks/repeat-times.dRbhJCV7.js";import{_ as n}from"./chunks/continuous_data_copy_diagram.VA_ibWhI.js";import{_ as p}from"./chunks/discontinuous_data_copy_diagram.dVxlyFZK.js";import{_ as t,o as l,a as c,b as i}from"./app.DKoEZOcr.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬出","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/cube_compute_store"},{"text":"DataCopy（L1ToGM高维切分数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L1ToGM_highdim_split"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L1ToGM_highdim_split.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L1ToGM_highdim_split.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"关键特性说明","slug":"关键特性说明","link":"#关键特性说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),o={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L1ToGM_highdim_split.md"};function e(r,a,d,_,h,u){return l(),c("div",null,[...a[0]||(a[0]=[i(`<div><article class="markdown-body"><h1>DataCopy（L1ToGM高维切分数据搬运）<span id="ZH-CN_TOPIC_0000002594407261"></span></h1><h2 id="产品支持情况">产品支持情况<span id="zh-cn_topic_0000002540558032_section796754519912"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<span id="zh-cn_topic_0000002540558032_section106841136114319"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>该接口主要实现将矩阵从L1 Buffer搬运至Global Memory，数据搬运时格式和内容保持不变。</p><p>高维切分是指能够通过配置数据块个数、单个数据块长度、地址偏移等搬运参数实现非连续搬运。</p><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000002540558032_section82039854412"></span><a class="header-anchor" href="#函数原型">​</a></h2><p>接口同时支持非连续搬运和连续搬运：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div><p>对于连续搬运场景，推荐使用<a href="DataCopy_L1ToGM_continuous.html">DataCopy（L1ToGM连续数据搬运）</a>。</p><h2 id="参数说明">参数说明<span id="zh-cn_topic_0000002540558032_section16128134420472"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数或者目的操作数的数据类型。支持的数据类型请参考<a href="#zh-cn_topic_0000002540558032_section4219135304818">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为GlobalTensor，存储位置为Global Memory，地址需要1字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor，存储位置为L1 Buffer，地址需要32字节对齐。</td></tr><tr><td>repeatParams</td><td>输入</td><td>搬运参数，类型为DataCopyParams。通过该参数可以配置搬运的数据块个数、长度、地址间隔等信息，同时支持非连续和连续搬运。<br>DataCopyParams参数说明请参考<a href="#zh-cn_topic_0000002540558032_table144203616291">表3</a>。</td></tr></tbody></table><p><strong>表3</strong> DataCopyParams结构体参数定义<a id="zh-cn_topic_0000002540558032_table144203616291"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>blockCount</td><td>搬运的数据块个数。uint16_t类型，取值范围为blockCount∈[0, 4095]，默认值为1。<br><strong>注：blockCount = 0表示不执行搬运，该接口将被视为NOP（空操作）</strong>。</td></tr><tr><td>blockLen</td><td>搬运的每个数据块长度。uint16_t类型，取值范围为blockLen∈[0, 65535]，单位：DataBlock（32字节）。<br><strong>注：blockLen = 0表示不执行搬运，该接口将被视为NOP（空操作）</strong>。</td></tr><tr><td>srcGap</td><td>源操作数相邻数据块之间的间隔（即前一个数据块<strong>结束地址</strong>与后一个数据块<strong>起始地址</strong>的差值），uint16_t类型，取值范围为srcGap∈[0, 65535]，单位为DataBlock（32字节）。<br>• blockCount = 1时，srcGap无意义，设置为0即可。</td></tr><tr><td>dstGap</td><td>目的操作数相邻数据块之间的间隔（即前一个数据块<strong>结束地址</strong>与后一个数据块<strong>起始地址</strong>的差值），uint16_t类型，取值范围为dstGap∈[0, 65535]，单位为DataBlock（32字节）。<br>• blockCount = 1时，dstGap无意义，设置为0即可。</td></tr></tbody></table><p>下图呈现了DataCopyParams结构体参数的使用方法，样例中完成了2个连续传输数据块的搬运，每个数据块含有8个DataBlock，源操作数相邻数据块之间无间隔，目的操作数相邻数据块尾与头之间间隔1个DataBlock。</p><p><img src="`+s+'" alt></p><h2 id="数据类型">数据类型<a id="zh-cn_topic_0000002540558032_section4219135304818"></a><a class="header-anchor" href="#数据类型">​</a></h2><p>源矩阵和目的矩阵支持的数据类型保持一致。</p><div data-filter="A3"><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t、double。</p></div><div data-filter="x90"><p>针对Kirin X90，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</p></div><div data-filter="9030"><p>Kirin 9030，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float、int64_t、uint64_t、double。</p></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002540558032_section2045914466492"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>位于L1 Buffer的源地址必须32字节对齐，位于Global Memory的目的地址必须1字节对齐。</li><li>当DataCopyParams结构体参数blockCount、blockLen任意一个值为0时，该指令不会执行。</li></ul><div data-filter="A3,910b"><ul><li>针对如下产品型号： <span data-filter="A3"> Atlas A3 训练系列产品/Atlas A3 推理系列产品 </span><span data-filter="910b"> Atlas A2 训练系列产品/Atlas A2 推理系列产品 </span> 在跨卡通信算子开发场景，DataCopy类接口支持跨卡数据搬运，仅支持HCCS物理链路，不支持其他通路；开发者开发过程中，需要关注涉及卡间通信的物理通路，可通过npu-smi info -t topo命令查询HCCS物理链路。</li></ul></div><ul><li><p>DataCopyParams结构体参数的值需在取值范围内：</p><p><strong>表4</strong> DataCopyParams结构体参数取值范围</p><table><thead><tr><th>参数名称</th><th>取值范围</th></tr></thead><tbody><tr><td>blockCount</td><td>[1, 4095]</td></tr><tr><td>blockLen</td><td>[1, 65535]</td></tr><tr><td>srcGap</td><td>[0, 65535]</td></tr><tr><td>dstGap</td><td>[0, 65535]</td></tr></tbody></table></li></ul><h2 id="关键特性说明">关键特性说明<span id="zh-cn_topic_0000002540558032_section1084342081618"></span><a class="header-anchor" href="#关键特性说明">​</a></h2><p><strong>连续搬运</strong></p><p>针对连续搬运场景，推荐使用<a href="DataCopy_L1ToGM_continuous.html#ZH-CN_TOPIC_0000002563687928">DataCopy（L1ToGM连续数据搬运）</a>，以下示例仅展示高维切分数据搬运接口具有连续搬运能力。</p><p>以half数据类型为例，源操作数的shape为1 * 128。</p><p><a href="#zh-cn_topic_0000002540558032_fig187115784817">图1</a>将源操作数中128个元素连续搬运至目的操作数，DataCopyParams结构体参数配置如下：</p><ul><li>blockCount = 1，搬运1个数据块，表示连续搬运。</li><li>blockLen = 8，一个数据块长度为8个DataBlock。</li><li>srcGap = 0，源操作数相邻数据块之间的间隔为0。</li><li>dstGap = 0，目的操作数相邻数据块之间的间隔为0。</li></ul><p><strong>图1</strong> 连续搬运示意图<a id="zh-cn_topic_0000002540558032_fig187115784817"></a></p><p><img src="'+n+'" alt></p><p><strong>非连续搬运</strong></p><p>以half数据类型为例，源操作数的shape为1 * 112。</p><p><a href="#zh-cn_topic_0000002540558032_fig123821924175312">图2</a>将源操作数中非连续数据搬运至目的操作数，DataCopyParams结构体参数配置如下：</p><ul><li>blockCount= 2，搬运2个数据块。</li><li>blockLen= 3，一个数据块的长度为3个DataBlock。</li><li>srcGap= 1，源操作数相邻数据块之间的间隔为1。</li><li>dstGap= 2，目的操作数相邻数据块之间的间隔为2。</li></ul><p><strong>图2</strong> 非连续搬运示意图<a id="zh-cn_topic_0000002540558032_fig123821924175312"></a></p><p><img src="'+p+`" alt></p><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002540558032_section088124295117"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>以<a href="#zh-cn_topic_0000002540558032_fig123821924175312">图2</a>所示场景为例，展示非连续搬运时的调用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">112</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>

<span class="c1">// 源操作数：L1 Buffer，按“48个有效half + 16个跳过half + 48个有效half”排布。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="n">a1Addr</span><span class="p">,</span><span class="w"> </span><span class="n">srcElemCount</span><span class="p">);</span>

<span class="c1">// 目的操作数：GM上预留128个half，两个有效数据块之间保留32个half间隔。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstGm</span><span class="p">;</span>
<span class="n">dstGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">dstElemCount</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">;</span>
<span class="c1">// 搬运2个连续传输数据块。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 每个数据块长度为3个DataBlock。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// 源端相邻数据块之间跳过1个DataBlock。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">srcGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="c1">// 目的端相邻数据块之间间隔2个DataBlock。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGm</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const v=t(o,[["render",e]]);export{g as __pageData,v as default};
